    <?php if ($section === "configuracoes" && !empty($history)): ?><div class="gd-academy-card mt15"><h3>Histórico recente</h3><div class="gd-academy-list"><?php foreach ($history as $entry): ?><div class="gd-academy-list-item"><div class="gd-academy-list-item-main"><strong><?php echo esc($entry->action); ?> · <?php echo esc($entry->entity_type); ?></strong><small><?php echo esc($entry->created_at); ?> · usuário #<?php echo (int) $entry->actor_id; ?></small></div></div><?php endforeach; ?></div></div><?php endif; ?>
</div>
<?php echo view('grupo_donato_gestao\Operacional\Views\_academy_actions'); ?>
